// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 amount) public {
        // Admissible domain: any non-empty value other than exactly 10 ether.
        vm.assume(amount != 10 ether);

        vm.deal(address(this), amount);

        // Drive c through its (unnamed) payable fallback via a low-level call.
        (bool ok, ) = address(c).call{value: amount}("");

        // General rule: any fallback invocation whose msg.value is NOT 10 ether
        // must be REJECTED by C (revert). The mutant accepts such calls
        // (require(msg.value != 10 ether)), so for some amount != 10 ether
        // the mutant sets ok = true and breaks this rule.
        assertTrue(!ok, "fallback with value != 10 ether must revert");
    }
}
